// 資料ごとのスクリプト deck.ts が、名前 slide-deck で import type する型 (計画の KTD2)。
// deck.ts はプラグインのモジュールを実行時に import しないので、ここからは型だけを書き出す。

import type { Parts } from "./data/parts.ts";
import type { SlideFigure } from "./data/types.ts";
import type { Theme } from "./data/theme.ts";

export type {
  ArrowOptions,
  BadgeOptions,
  BoxOptions,
  BulletsOptions,
  CardOptions,
  MarginInput,
  Parts,
  RunInput,
  TextOptions,
} from "./data/parts.ts";
export type { AccentColor, SchemeColorName, Theme } from "./data/theme.ts";
export type {
  Deck,
  Fill,
  LineElement,
  Margin,
  Outline,
  Paragraph,
  Rect,
  ShapeElement,
  ShapeGeometry,
  ShapeKind,
  Slide,
  SlideElement,
  SlideFigure,
  TextBody,
  TextBoxElement,
  TextRun,
  ThemeColorName,
} from "./data/types.ts";

/** 資料ごとのスクリプトの関数が返す値。資料のテーマと、キーごとの図。 */
export interface DeckScriptResult {
  theme: Theme;
  slides: SlideFigure[];
}

/**
 * 資料ごとのスクリプトが default export する関数の型。
 * 部品の関数の集まりを引数で受け取り、テーマとキーごとの図を返す。
 */
export type DeckScript = (p: Parts) => DeckScriptResult;
// スライドのデータの型。
// 資料ごとのスクリプト deck.ts が部品の関数で作り、PowerPoint の書き出しと Google スライドの指示の作成が読む。
// 2 つの書き出しの処理の両方が扱える要素だけを持つ (計画の KTD1)。
// 位置と大きさはインチ、文字の大きさ・線の幅・内側の余白・段落の後の間隔はポイントで持つ。
// 値はすべて決まった値で持ち、省略やデフォルト値を残さない。書き出しの処理がデフォルト値を知らなくて済むようにするため。

import type { Theme } from "./theme.ts";

/** 図形と文字の色に使う、テーマの色の名前。色の値ではなく、この名前で指定する。 */
export type ThemeColorName =
  | "dk1"
  | "lt1"
  | "dk2"
  | "lt2"
  | "accent1"
  | "accent2"
  | "accent3"
  | "accent4"
  | "accent5"
  | "accent6";

/** 位置と大きさ (インチ)。x と y は左上の角。 */
export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** 塗りつぶし。transparency は透明度 (0〜100。0 が不透明)。 */
export interface Fill {
  color: ThemeColorName;
  transparency: number;
}

/** 図形の枠線。width はポイント。 */
export interface Outline {
  color: ThemeColorName;
  width: number;
  dashed: boolean;
}

/** 文字の一部分と、その書式。link は文字に付けるリンクの URL (無ければ null)。 */
export interface TextRun {
  text: string;
  fontSize: number;
  bold: boolean;
  color: ThemeColorName;
  link: string | null;
}

/**
 * 段落。bullet が true なら箇条書きの項目にする。
 * どの段落も部分を 1 つ以上持つ。文字の無い段落 (空行など) は、文字が空の部分を 1 つ持ち、その部分が段落の文字の大きさ・太字・色を表す。
 */
export interface Paragraph {
  runs: TextRun[];
  bullet: boolean;
}

/** 内側の余白 (ポイント)。 */
export interface Margin {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/** 図形や文字の箱の中の文字。paraSpaceAfter は段落の後の間隔 (ポイント。0 なら間隔を空けない)。 */
export interface TextBody {
  paragraphs: Paragraph[];
  align: "left" | "center" | "right";
  valign: "top" | "middle" | "bottom";
  margin: Margin;
  paraSpaceAfter: number;
}

/**
 * 図形の形。名前は PowerPoint のファイルの形式 (Office Open XML) の形の名前に合わせた。
 * roundRect は角の丸い四角、rect は四角、ellipse は円、can は円柱、chevron は山形、homePlate は五角形の矢印。
 */
export type ShapeKind = "roundRect" | "rect" | "ellipse" | "can" | "chevron" | "homePlate";

/** 形と、形ごとの値。角の丸い四角だけが角の半径 (インチ) を持つ。 */
export type ShapeGeometry =
  | { shape: "roundRect"; radius: number }
  | { shape: Exclude<ShapeKind, "roundRect"> };

/** 図形。中に文字を持てる (文字が無ければ text は null)。枠線が無ければ outline は null。 */
export type ShapeElement = Rect &
  ShapeGeometry & {
    kind: "shape";
    fill: Fill;
    outline: Outline | null;
    text: TextBody | null;
    name: string | null;
  };

/** 塗りつぶしと枠線の無い、文字の箱。 */
export type TextBoxElement = Rect & {
  kind: "textBox";
  text: TextBody;
  name: string | null;
};

/**
 * 線。位置と大きさは、始点と終点を囲む四角で持つ。
 * 始点が終点より右なら flipH、下なら flipV を true にして、向きを表す。
 * endArrow は終点に、startArrow は始点に、矢じりを付けるか。width はポイント。
 * 名前は Google スライドの API の線のプロパティ (endArrow・startArrow) に合わせた。
 * PowerPoint のファイルの形式では、要素 a:headEnd が始点の、a:tailEnd が終点の矢じりを表すので、
 * PowerPoint の書き出しでは endArrow を a:tailEnd に、startArrow を a:headEnd に対応させる。
 */
export type LineElement = Rect & {
  kind: "line";
  flipH: boolean;
  flipV: boolean;
  color: ThemeColorName;
  width: number;
  dashed: boolean;
  endArrow: boolean;
  startArrow: boolean;
};

/** スライドの要素。 */
export type SlideElement = ShapeElement | TextBoxElement | LineElement;

/**
 * 1 つのキーの図。資料ごとのスクリプトが、部品の関数で要素を足して作る。
 * elements の順序は足した順序で、後の要素ほど前面に重なる。
 */
export interface SlideFigure {
  readonly key: string;
  readonly elements: SlideElement[];
}

/**
 * 1 枚のスライドのデータ。題名・一言・発表者ノート (notes) は構成案から、図 (elements) は資料ごとのスクリプトから取る (計画の R8)。
 */
export interface Slide {
  key: string;
  title: string;
  takeaway: string;
  notes: string;
  elements: SlideElement[];
}

/** 1 つの資料のデータ。2 つの書き出しの処理は、これだけを読む。slides の順序は構成案のスライドの順序。 */
export interface Deck {
  theme: Theme;
  slides: Slide[];
}
// テーマ。資料ごとに、6 つのアクセント色の値と意味の名前・フォントを決める (計画の R11)。
// 図形の色はテーマの色の名前で指定し、色の値はテーマだけが持つ。

/** アクセント色。color は 16 進数 6 桁の RGB の値 (例: "0F8B8D")、meaning はその色に割り当てた意味 (例: "新しい版")。 */
export interface AccentColor {
  color: string;
  meaning: string;
}

/**
 * 資料のテーマ。
 * colors はアクセント色以外の 6 色 (dk1 は文字、lt1 は背景、dk2 は補助の文字、lt2 は補助の背景、hlink はリンク、folHlink は開いたリンク)。
 * accents は 6 つのアクセント色で、どれも省略できない。
 * name はテーマの名前で、PowerPoint のファイルに書き込む。
 */
export interface Theme {
  name: string;
  fonts: {
    heading: string;
    body: string;
  };
  colors: {
    dk1: string;
    lt1: string;
    dk2: string;
    lt2: string;
    hlink: string;
    folHlink: string;
  };
  accents: {
    accent1: AccentColor;
    accent2: AccentColor;
    accent3: AccentColor;
    accent4: AccentColor;
    accent5: AccentColor;
    accent6: AccentColor;
  };
}

/** テーマの 12 色の名前。PowerPoint のファイルの形式の配色の名前と同じ。 */
export type SchemeColorName = keyof Theme["colors"] | keyof Theme["accents"];

/** テーマの 12 色の名前を、配色の順序で並べた配列。 */
export const SCHEME_COLOR_NAMES: readonly SchemeColorName[] = [
  "dk1",
  "lt1",
  "dk2",
  "lt2",
  "accent1",
  "accent2",
  "accent3",
  "accent4",
  "accent5",
  "accent6",
  "hlink",
  "folHlink",
];

/** テーマの 12 色の名前と値の対応を返す。PowerPoint のファイルと Google スライドに配色を書き込むときに使う。 */
export function schemeColorValues(theme: Theme): Record<SchemeColorName, string> {
  const { colors, accents } = theme;
  return {
    ...colors,
    accent1: accents.accent1.color,
    accent2: accents.accent2.color,
    accent3: accents.accent3.color,
    accent4: accents.accent4.color,
    accent5: accents.accent5.color,
    accent6: accents.accent6.color,
  };
}

const RGB_HEX = /^[0-9A-Fa-f]{6}$/;

/**
 * テーマの値の誤りを、すべて集めて返す。誤りが無ければ空の配列を返す。
 * 型では検査できない、色の値の形 (16 進数 6 桁。"#" を付けない) と、空の名前・フォント・意味を検査する。
 */
export function checkTheme(theme: Theme): string[] {
  const errors: string[] = [];
  if (theme.name.trim() === "") errors.push("テーマの name が空");
  if (theme.fonts.heading.trim() === "") errors.push("テーマの fonts.heading が空");
  if (theme.fonts.body.trim() === "") errors.push("テーマの fonts.body が空");
  const values = schemeColorValues(theme);
  for (const name of SCHEME_COLOR_NAMES) {
    const value = values[name];
    if (!RGB_HEX.test(value)) {
      errors.push(`テーマの色 ${name} の値 ${JSON.stringify(value)} が、16 進数 6 桁 (例: "0F8B8D") ではない`);
    }
  }
  for (const [name, accent] of Object.entries(theme.accents)) {
    if (accent.meaning.trim() === "") errors.push(`テーマの色 ${name} の meaning が空`);
  }
  return errors;
}

