166	/**
167	 * 入力の部分の配列を段落に分ける。分け方は、型 RunInput の説明の規則 1〜6 のとおり。
168	 */
169	function toParagraphs(t: TextInput, d: RunDefaults): Paragraph[] {
170	  const inputs: RunInput[] = typeof t === "string" ? [{ text: t }] : t;
171	  let current: Paragraph = { runs: [], bullet: false };
172	  const paragraphs: Paragraph[] = [current];
173	  // fromBreakOnly は、最後の段落が区切りで作られ、まだ行が入っていないか (規則 5 で使う)。
174	  // 関数 breakParagraph の中でも書き換えるので、変数ではなくオブジェクトのプロパティに持つ
175	  // (変数にすると、TypeScript の型の検査がクロージャの中の書き換えを考慮せず、常に false と見なす)
176	  const state = { fromBreakOnly: false };
177	  const breakParagraph = (): void => {
178	    current = { runs: [], bullet: false };
179	    paragraphs.push(current);
180	    state.fromBreakOnly = true;
181	  };
182	  for (const input of inputs) {
183	    // 規則 3
184	    if (input.bullet === true && current.runs.length > 0) breakParagraph();
185	    const lines = input.text.split("\n");
186	    lines.forEach((line, i) => {
187	      // 規則 2
188	      if (i > 0) breakParagraph();
189	      if (i > 0 && i === lines.length - 1 && line === "" && input.breakLine !== true) return;
190	      state.fromBreakOnly = false;
191	      if (input.bullet === true) current.bullet = true;
192	      const run = {
193	        text: line,
194	        fontSize: input.fontSize ?? d.fontSize,
195	        bold: input.bold ?? d.bold,
196	        color: input.color ?? d.color,
197	        link: input.link ?? null,
198	      };
199	      if (line === "") {
200	        // 規則 4。空の行の TextRun は、段落にまだ TextRun が無いときだけ足す (最初の空の行だけを持つため)
201	        if (current.runs.length === 0) current.runs.push(run);
202	        return;
203	      }
204	      // 規則 4。空でない行の TextRun を足すときは、空の行の TextRun を除く
205	      current.runs = current.runs.filter((r) => r.text !== "");
206	      current.runs.push(run);
207	    });
208	    // 規則 1
209	    if (input.breakLine === true) breakParagraph();
210	  }
211	  // 規則 5
212	  if (paragraphs.length > 1 && state.fromBreakOnly) paragraphs.pop();
213	  // 規則 6
214	  for (const p of paragraphs) {
215	    if (p.runs.length === 0) {
216	      p.runs.push({ text: "", fontSize: d.fontSize, bold: d.bold, color: d.color, link: null });
217	    }
218	  }
219	  return paragraphs;
220	}
221	
222	/** 段落に、空でない文字の部分が無いか。 */
223	function isBlank(p: Paragraph): boolean {
224	  return p.runs.every((r) => r.text === "");
225	}
226	
227	function hasText(paragraphs: Paragraph[]): boolean {
228	  return paragraphs.some((p) => !isBlank(p));
229	}
230	
231	/** 資料ごとのスクリプトが、キーごとの空の図を作る。部品の関数は、この図に要素を足す。 */
232	export function slide(key: string): SlideFigure {
233	  return { key, elements: [] };
234	}
235	
236	/**
237	 * 文字の入った箱を足す。形のデフォルト値は角の丸い四角。
238	 * 文字が空 ("" か空の配列) なら、文字を持たない図形になる (塗りつぶしだけの四角などに使う)。
239	 */
240	export function box(
241	  s: SlideFigure,
242	  x: number,
243	  y: number,
244	  w: number,
245	  h: number,
246	  t: string,
247	  o?: BoxOptions,
248	): void;
249	// 文字列と配列を 1 つの引数の型 (string | RunInput[]) にまとめると、配列に書いた bold や link を、
250	// 規則 no-deprecated が String.prototype の非推奨のメソッドとして誤って指摘する。
251	// 資料ごとのスクリプトも同じ規則で検査するので、オーバーロードに分けたまま、規則 unified-signatures の指摘の対象から除く
252	export function box(
253	  s: SlideFigure,
254	  x: number,
255	  y: number,
256	  w: number,
257	  h: number,
258	  // eslint-disable-next-line @typescript-eslint/unified-signatures
259	  t: RunInput[],
260	  o?: BoxOptions,
261	): void;
262	export function box(
263	  s: SlideFigure,
264	  x: number,
265	  y: number,
266	  w: number,
267	  h: number,
268	  t: TextInput,
269	  o: BoxOptions = {},
270	): void {
271	  const paragraphs = toParagraphs(t, {
272	    fontSize: o.fontSize ?? 14,
273	    bold: o.bold ?? false,
274	    color: o.color ?? "dk1",
275	  });
276	  const text: TextBody | null = hasText(paragraphs)
277	    ? {
278	        paragraphs,
279	        align: o.align ?? "center",
280	        valign: o.valign ?? "middle",
281	        margin: toMargin(o.margin ?? 6),
282	        paraSpaceAfter: 0,
283	      }
284	    : null;
285	  const shape = o.shape ?? "roundRect";
286	  const common = {
287	    kind: "shape" as const,
288	    x,
289	    y,
290	    w,
291	    h,
292	    fill: { color: o.fill ?? "lt1", transparency: o.tr ?? 0 },
293	    outline:
294	      o.line === undefined ? null : { color: o.line, width: o.lineW ?? 1, dashed: o.dash ?? false },
295	    text,
296	    name: o.name ?? null,
297	  };
298	  const element: ShapeElement =
299	    shape === "roundRect" ? { ...common, shape, radius: o.radius ?? 0.08 } : { ...common, shape };
300	  s.elements.push(element);
301	}
302	
303	/** 塗りつぶしと枠線の無い、文字の箱を足す。 */
304	export function text(
305	  s: SlideFigure,
306	  t: string,
307	  x: number,
308	  y: number,
309	  w: number,
310	  h: number,
311	  o?: TextOptions,
312	): void;
313	// オーバーロードに分ける理由は、関数 box と同じ
314	export function text(
315	  s: SlideFigure,
316	  // eslint-disable-next-line @typescript-eslint/unified-signatures
317	  t: RunInput[],
318	  x: number,
319	  y: number,
320	  w: number,
321	  h: number,
322	  o?: TextOptions,
323	): void;
324	export function text(
325	  s: SlideFigure,
326	  t: TextInput,
327	  x: number,
328	  y: number,
329	  w: number,
330	  h: number,
331	  o: TextOptions = {},
332	): void {
333	  const element: TextBoxElement = {
334	    kind: "textBox",
335	    x,
336	    y,
337	    w,
338	    h,
339	    text: {
340	      paragraphs: toParagraphs(t, {
341	        fontSize: o.fontSize ?? 14,
342	        bold: o.bold ?? false,
343	        color: o.color ?? "dk1",
344	      }),
345	      align: o.align ?? "left",
346	      valign: o.valign ?? "top",
347	      margin: toMargin(o.margin ?? 0),
348	      paraSpaceAfter: o.psa ?? 0,
349	    },
350	    name: o.name ?? null,
351	  };
352	  s.elements.push(element);
353	}
354	
355	/**
356	 * 始点 (x1, y1) から終点 (x2, y2) への矢印を足す。
357	 * 線の位置と大きさは 2 点を囲む四角で持ち、終点が始点より左なら左右を、上なら上下を反転するフラグを立てる。
358	 */
359	export function arrow(
360	  s: SlideFigure,
361	  x1: number,
362	  y1: number,
363	  x2: number,
364	  y2: number,
365	  o: ArrowOptions = {},
366	): void {
367	  s.elements.push({
368	    kind: "line",
369	    x: Math.min(x1, x2),
370	    y: Math.min(y1, y2),
371	    w: Math.abs(x2 - x1),
372	    h: Math.abs(y2 - y1),
373	    flipH: x2 < x1,
374	    flipV: y2 < y1,
375	    color: o.color ?? "dk2",
376	    width: o.width ?? 1.5,
377	    dashed: o.dash ?? false,
378	    endArrow: o.noHead !== true,
379	    startArrow: o.both === true,
380	  });
381	}
382	
383	/** 番号の入った円を足す。(x, y) は円を囲む四角の左上の角、d は直径 (インチ)。 */
384	export function badge(
385	  s: SlideFigure,
386	  n: number | string,
387	  x: number,
388	  y: number,
389	  d: number,
390	  o: BadgeOptions = {},
391	): void {
392	  s.elements.push({
393	    kind: "shape",
394	    shape: "ellipse",
395	    x,
396	    y,
397	    w: d,
398	    h: d,
399	    fill: { color: o.fill ?? "accent1", transparency: 0 },
400	    outline: null,
401	    text: {
402	      paragraphs: toParagraphs(String(n), {
403	        fontSize: o.fontSize ?? 12,
404	        bold: true,
405	        color: "lt1",
406	      }),
407	      align: "center",
408	      valign: "middle",
409	      margin: toMargin(0),
410	      paraSpaceAfter: 0,
411	    },
412	    name: null,
413	  });
414	}
415	
416	/**
417	 * 一言 (そのスライドで伝えたいことの 1 文) を、スライドの下の決まった位置の文字の箱として足す。
418	 * 一言は構成案から読むので、資料ごとのスクリプトには渡さない (型 Parts に含めない)。
419	 */
420	export function takeaway(s: SlideFigure, t: string): void {
421	  text(s, t, 0.5, 4.78, 8.5, 0.42, {
422	    fontSize: 14,
423	    bold: true,
424	    color: "dk1",
425	    valign: "middle",
426	    name: "takeaway",
427	  });
428	}
429	
430	/** 図の部分をまとめる背景のカード (文字の無い、角の丸い四角) を足す。 */
431	export function card(
432	  s: SlideFigure,
433	  x: number,
434	  y: number,
435	  w: number,
436	  h: number,
437	  o: CardOptions = {},
438	): void {
439	  s.elements.push({
440	    kind: "shape",
441	    shape: "roundRect",
442	    radius: 0.1,
443	    x,
444	    y,
445	    w,
446	    h,
447	    fill: { color: o.fill ?? "lt2", transparency: o.tr ?? 0 },
448	    outline: null,
449	    text: null,
450	    name: o.name ?? null,
451	  });
452	}
453	
454	/**
455	 * 箇条書きの文字を作る。戻り値を関数 text や box に渡す。項目ごとに段落を分ける。
456	 * 指定しなかった書式は項目に書かず、受け取る部品の関数の書式を使う (型 RunInput の説明のとおり)。
457	 */
458	export function bullets(items: string[], o: BulletsOptions = {}): RunInput[] {
459	  return items.map((t, i) => {
460	    const item: RunInput = { text: t, bullet: true, breakLine: i < items.length - 1 };
461	    if (o.fontSize !== undefined) item.fontSize = o.fontSize;
462	    if (o.color !== undefined) item.color = o.color;
463	    return item;
464	  });
465	}
466	
467	/** 資料ごとのスクリプトに渡す、部品の関数の集まり (計画の KTD2)。 */
468	export interface Parts {
469	  slide: typeof slide;
470	  box: typeof box;
471	  text: typeof text;
472	  arrow: typeof arrow;
473	  badge: typeof badge;
474	  card: typeof card;
475	  bullets: typeof bullets;
476	}
477	
478	/** 資料ごとのスクリプトに渡す、部品の関数の集まりの値。 */
479	export const parts: Parts = { slide, box, text, arrow, badge, card, bullets };
